from executor import ToolExecutor
from registry import build_telecom_registry


def main():
    registry = build_telecom_registry()
    executor = ToolExecutor(registry)

    # Simulated authenticated application context.
    authorized_customer_id = "CUST-1001"

    # Simulated tool request generated by an LLM.
    tool_name = "get_service_status"

    arguments = {"customer_id": "CUST-1001"}

    result = executor.execute(
        tool_name=tool_name,
        arguments=arguments,
        authorized_customer_id=authorized_customer_id,
    )

    print(result)


if __name__ == "__main__":
    main()
